1: //! The retry-budget calculation. Shared by every caller that plans retries.
2: 
3: /// How many attempts a job gets, and how long to wait between them.
4: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
5: pub struct Budget {
6:     pub attempts: u32,
7:     pub backoff_ms: u64,
8: }
9: 
10: /// Plan the retry budget for a job.
11: ///
12: /// `weight` is the job's cost class (1 = cheap, higher = more expensive). A more
13: /// expensive job gets fewer attempts and waits longer between them.
14: pub fn plan(weight: u32) -> Budget {
15:     let attempts = if weight >= 4 { 2 } else { 5 };
16:     Budget { attempts, backoff_ms: 100 * weight as u64 }
17: }

