1: // Contract test for the retry budget. FROZEN: a solver must not modify this file.
2: #[path = "report.rs"]
3: mod report;
4: 
5: use report::admin;
6: use report::admin::queue;
7: use report::admin::queue::budget::{plan, Budget};
8: 
9: // `plan` must now take the deadline the schedule has to fit inside, and never
10: // plan a schedule that overruns it: attempts are cut until
11: // `attempts as u64 * backoff_ms <= deadline_ms`, with a floor of one attempt.
12: 
13: #[test]
14: fn a_generous_deadline_leaves_the_old_plan_alone() {
15:     // weight 1: 5 attempts, 100ms backoff = 500ms, fits in 30s.
16:     assert_eq!(plan(1, 30_000), Budget { attempts: 5, backoff_ms: 100 });
17: }
18: 
19: #[test]
20: fn a_tight_deadline_cuts_attempts() {
21:     // weight 1 wants 5 x 100ms = 500ms; only 250ms available => 2 attempts.
22:     assert_eq!(plan(1, 250), Budget { attempts: 2, backoff_ms: 100 });
23: }
24: 
25: #[test]
26: fn one_attempt_is_the_floor() {
27:     // weight 8: backoff 800ms, and 100ms of budget. Still one attempt.
28:     assert_eq!(plan(8, 100), Budget { attempts: 1, backoff_ms: 800 });
29: }
30: 
31: // --- the four call sites, each with its own right answer ---
32: 
33: #[test]
34: fn an_ordinary_job_uses_the_deadline_its_caller_passed() {
35:     // The caller says 250ms, so the job gets the 250ms plan, not the 30s one.
36:     let job = queue::enqueue("resize", 1, 250);
37:     assert_eq!(job.budget, Budget { attempts: 2, backoff_ms: 100 });
38: 
39:     // ...and a different caller deadline gives a different plan, so the value
40:     // really is threaded through rather than hard-coded.
41:     let job = queue::enqueue("resize", 1, 30_000);
42:     assert_eq!(job.budget, Budget { attempts: 5, backoff_ms: 100 });
43: }
44: 
45: #[test]
46: fn a_probe_is_bound_by_the_liveness_window() {
47:     // PROBE_DEADLINE_MS is 1000ms; weight 1 backs off 100ms, so 5 attempts
48:     // (500ms) still fit -- but the deadline passed must be the probe's own,
49:     // which the next assertion pins.
50:     let job = queue::enqueue_probe("ping");
51:     assert_eq!(job.weight, 1);
52:     assert_eq!(job.budget, plan(1, queue::PROBE_DEADLINE_MS));
53:     // A probe must NOT be planned against the admin or status-page deadline.
54:     assert_ne!(queue::PROBE_DEADLINE_MS, admin::ADMIN_DEADLINE_MS);
55: }
56: 
57: #[test]
58: fn a_probe_schedule_fits_inside_one_second() {
59:     let job = queue::enqueue_probe("ping");
60:     let span = job.budget.attempts as u64 * job.budget.backoff_ms;
61:     assert!(span <= queue::PROBE_DEADLINE_MS, "probe schedule {span}ms overruns the liveness window");
62: }
63: 
64: #[test]
65: fn an_admin_rebuild_uses_the_five_minute_deadline() {
66:     // weight 8 => 2 attempts, 800ms backoff = 1600ms, well inside 300s.
67:     assert_eq!(admin::rebuild_budget(), Budget { attempts: 2, backoff_ms: 800 });
68:     assert_eq!(admin::rebuild_budget(), plan(admin::ADMIN_WEIGHT, admin::ADMIN_DEADLINE_MS));
69: }
70: 
71: #[test]
72: fn the_status_page_summarises_against_its_own_refresh_window() {
73:     // 30s refresh: weight 8 wants 2 x 800ms = 1600ms, which fits.
74:     assert_eq!(report::summarise(8), "2x/800ms");
75:     // But a weight the refresh window cannot hold is cut. weight 200 backs off
76:     // 20000ms; two attempts would be 40s > 30s, so one attempt.
77:     assert_eq!(report::summarise(200), "1x/20000ms");
78:     // Pin it to the page's own constant, not to some other module's.
79:     let b = plan(200, report::STATUS_PAGE_DEADLINE_MS);
80:     assert_eq!(report::summarise(200), format!("{}x/{}ms", b.attempts, b.backoff_ms));
81: }

