1: //! Renders a one-line budget summary for the status page.
2: 
3: #[path = "admin.rs"]
4: pub mod admin;
5: 
6: use admin::queue::budget::plan;
7: 
8: /// The status page recomputes every 30s, so nothing it summarises may plan a
9: /// schedule longer than that.
10: pub const STATUS_PAGE_DEADLINE_MS: u64 = 30_000;
11: 
12: /// Summarise the budget a job of `weight` would get, as `"<n>x/<ms>ms"`.
13: pub fn summarise(weight: u32) -> String {
14:     let b = plan(weight);
15:     format!("{}x/{}ms", b.attempts, b.backoff_ms)
16: }

